using System;using System.IO;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Windows.Forms;
namespace FortsStudio {
 public static class AudioTools {
  [DllImport("winmm.dll",CharSet=CharSet.Unicode)]static extern int mciSendString(string command,StringBuilder result,int size,IntPtr handle);
  public static double Duration(byte[] data,string name){try{if(Path.GetExtension(name).Equals(".wav",StringComparison.OrdinalIgnoreCase)){using(var r=new BinaryReader(new MemoryStream(data))){if(new string(r.ReadChars(4))!="RIFF")return 2;r.ReadInt32();r.ReadInt32();int bytes=0,length=0;while(r.BaseStream.Position+8<=r.BaseStream.Length){string id=new string(r.ReadChars(4));int size=r.ReadInt32();long next=r.BaseStream.Position+size+(size%2);if(id=="fmt "&&size>=16){r.ReadInt16();r.ReadInt16();r.ReadInt32();bytes=r.ReadInt32();}if(id=="data")length=size;if(next>r.BaseStream.Length)break;r.BaseStream.Position=next;}if(bytes>0&&length>0)return (double)length/bytes;}}
    int start=0;if(data.Length>10&&data[0]=='I'&&data[1]=='D'&&data[2]=='3')start=10+((data[6]&127)<<21)+((data[7]&127)<<14)+((data[8]&127)<<7)+(data[9]&127);double seconds=0;int frames=0;int[] rates={44100,48000,32000};int[] high={0,32,40,48,56,64,80,96,112,128,160,192,224,256,320};int[] low={0,8,16,24,32,40,48,56,64,80,96,112,128,144,160};for(int i=start;i+4<data.Length;){if(data[i]!=255||(data[i+1]&224)!=224){i++;continue;}int version=(data[i+1]>>3)&3,layer=(data[i+1]>>1)&3,br=data[i+2]>>4,sr=(data[i+2]>>2)&3;if(version==1||layer!=1||br==0||br==15||sr==3){i++;continue;}int sample=rates[sr]/(version==3?1:version==2?2:4),bitrate=(version==3?high:low)[br],size=(version==3?144000:72000)*bitrate/sample+((data[i+2]>>1)&1);if(size<5||i+size>data.Length)break;seconds+=(version==3?1152.0:576.0)/sample;frames++;i+=size;}if(frames>0)return seconds;
   }catch{}return 2;}
  public static void Stop(){mciSendString("stop FmsStudioPreview",null,0,IntPtr.Zero);mciSendString("close FmsStudioPreview",null,0,IntPtr.Zero);}
  public static void Play(AudioClip clip){Stop();if(clip==null||clip.Data.Length==0)return;string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FortsModStudio2","audio-preview");Directory.CreateDirectory(folder);string file=Path.Combine(folder,clip.Id+Path.GetExtension(clip.FileName));File.WriteAllBytes(file,Assets.DataBytes(clip.Data));int result=mciSendString("open \""+file+"\" alias FmsStudioPreview",null,0,IntPtr.Zero);if(result!=0)throw new Exception("Не удалось воспроизвести этот аудиофайл.");mciSendString("setaudio FmsStudioPreview volume to "+(int)(Math.Min(1,clip.Volume)*1000),null,0,IntPtr.Zero);mciSendString("play FmsStudioPreview",null,0,IntPtr.Zero);}
 }
