  void DrawResources(FlowLayoutPanel f,Entity e){Header(f,"Игровое изображение");f.Controls.Add(Theme.Label(e.Kind=="devices"?"Своё изображение сооружения видно с самого начала постройки: части батарейки больше не подмешиваются.":"Свой спрайт заменяет основной спрайт выбранного шаблона Forts.",9));f.Controls.Add(Theme.Button(e.Texture.Length>0?"Заменить спрайт":"Загрузить спрайт",()=>ImportAsset(e,"texture")));if(e.Texture.Length>0)f.Controls.Add(Theme.Button("Штатное изображение",()=>{e.Texture="";Mark();ShowEntityTab(e,"Ресурсы");}));
   if(e.Kind=="materials"){
    var seamless=new UiCheckBox{Text="Бесшовный повтор текстуры",Checked=e.SeamlessTexture,AutoSize=true,ForeColor=Theme.Text,Margin=new Padding(0,10,0,5)};
