    f.Controls.Add(seamless);
    f.Controls.Add(Theme.Label("Для своего спрайта: плавно совмещает левый и правый края, чтобы при повторении вдоль балки не было стыков. Одинаково применяется в макете, иконке и моде. Исходное изображение хранится отдельно; настройку можно отключить.",9));
   }
   if(e.Kind=="devices"){
    if(e.Texture.Length>0||e.BuildStages.Count>0){var stage=e.BuildStages.OrderBy(x=>x.Progress).FirstOrDefault();var first=Assets.Image(stage!=null&&stage.Image.Length>0?stage.Image:e.Texture,project.GameRoot)??Assets.Body(e,project.GameRoot);if(first!=null){var sizeLabel=Theme.Label("",9);Action updateSize=()=>{var size=Raster.ModelSize(first,e.V("Scale",1));sizeLabel.Text="Размер в игре: "+(size.Width/2.0).ToString("0.#")+" × "+(size.Height/2.0).ToString("0.#")+" ед. · клетка макета — 50 ед.";};Number(f,"Масштаб своего изображения","Размер в игре: пиксели исходного холста × масштаб ÷ 2. Этот размер применяется при экспорте ко всем этапам.",e.V("Scale",1),.01,10,v=>{e.Values["Scale"]=v;updateSize();Mark();},"Scale");updateSize();f.Controls.Add(sizeLabel);}}
    DrawBuildStages(f,e);
   }
   if(e.Kind=="weapons")DrawWeaponArtwork(f,e);
   if(e.Kind=="projectiles"){Number(f,"Масштаб изображения снаряда","Меняет внешний размер мины; урон, массу и толщину столкновения задайте отдельно в параметрах.",e.ProjectileVisualScale,.1,10,v=>e.ProjectileVisualScale=v,"ProjectileVisualScale");if(e.Texture.Length>0)Number(f,"Длина своего спрайта, ед.","Длина изображения снаряда при масштабе 1. Прозрачные поля автоматически убираются.",e.ProjectileImageWidth,1,200,v=>e.ProjectileImageWidth=v,"ProjectileImageWidth");}
   Header(f,"Иконка в меню");using(var icon=Assets.HudCard(e,project.GameRoot,0)){var visible=icon.Clone(new Rectangle(0,0,128,170),PixelFormat.Format32bppArgb);f.Controls.Add(new PictureBox{Image=visible,Size=new Size(128,170),SizeMode=PictureBoxSizeMode.Zoom});}f.Controls.Add(Theme.Label("Изображение занимает верх карточки; нижняя светлая область отведена для цен Forts. Наведение, выбор и недоступность экспортируются отдельно.",9));f.Controls.Add(Theme.Button("Загрузить иконку",()=>ImportAsset(e,"icon")));if(e.Icon.Length>0)f.Controls.Add(Theme.Button("Создать автоматически",()=>{e.Icon="";Mark();ShowEntityTab(e,"Ресурсы");}));
   if(e.Kind!="materials"){var primary=new AudioClip{Id=e.Key+"_primary",Name=e.SoundName,FileName=e.SoundName,Data=e.Sound,Volume=e.SoundVolume};DrawAudio(f,e.Kind=="weapons"?"Выстрел":e.Kind=="projectiles"?"Попадание":"Начало строительства",primary,()=>{e.Sound=primary.Data;e.SoundName=primary.FileName;e.SoundVolume=primary.Volume;},false);if(e.Kind=="weapons"){var every=new UiCheckBox{Text="Звук для каждого выстрела в залпе",Checked=e.SoundEachShot,AutoSize=true,ForeColor=Theme.Text,Margin=new Padding(0,8,0,5)};every.CheckedChanged+=(s,ev)=>{e.SoundEachShot=every.Checked;Mark();};f.Controls.Add(every);f.Controls.Add(Theme.Label("Снято — один звук на весь залп. Установлено — звук на каждый последовательный выстрел. Одновременные дробинки считаются одним выстрелом.",9));}}
   if(e.Kind!="projectiles")DrawAudio(f,"Разрушение",e.DestroyAudio,Mark,false);f.Controls.Add(Theme.Label("Без своего звука разрушения используется штатный эффект и звук шаблона.",9));if(e.Kind=="devices"||e.Kind=="weapons")DrawAudio(f,"Работа устройства · повтор",e.WorkAudio,Mark,true);if(e.Kind=="projectiles")DrawAudio(f,"Полёт снаряда · повтор",e.FlightAudio,Mark,true);
  }
  void DrawAudio(FlowLayoutPanel f,string title,AudioClip clip,Action update,bool loop,Action refresh=null){Header(f,title);var line=new FlowLayoutPanel{AutoSize=true,Width=490};line.Controls.Add(Theme.Button(clip.Data.Length>0?"Заменить WAV / MP3":"Загрузить WAV / MP3",()=>Safe(()=>{using(var dlg=new OpenFileDialog{Filter="Звуки Forts|*.wav;*.mp3"}){if(UiDialogs.Show(dlg,this)!=DialogResult.OK)return;clip.Data=Assets.Import(dlg.FileName,false);clip.FileName=Path.GetFileName(dlg.FileName);clip.Name=Path.GetFileNameWithoutExtension(dlg.FileName);clip.Duration=AudioTools.Duration(Assets.DataBytes(clip.Data),clip.FileName);update();Mark();if(refresh!=null)refresh();else if(selected!=null)ShowEntityTab(selected,"Ресурсы");else ShowPalette();}})));if(clip.Data.Length>0){line.Controls.Add(Theme.Button("▶",()=>Safe(()=>AudioTools.Play(clip))));line.Controls.Add(Theme.Button("■",AudioTools.Stop));line.Controls.Add(Theme.Button("Стандарт / убрать",()=>{clip.Data="";clip.FileName="";clip.Name="";update();Mark();if(refresh!=null)refresh();else if(selected!=null)ShowEntityTab(selected,"Ресурсы");else ShowPalette();}));}f.Controls.Add(line);if(clip.Data.Length>0)f.Controls.Add(Theme.Label(clip.FileName,9));Number(f,"Громкость, %","100% — исходный уровень. 0% — без звука. Усиление выше 100% может дать перегрузку.",clip.Volume*100,0,200,v=>{clip.Volume=v/100;update();},"Volume");if(loop&&clip.Data.Length>0)Number(f,"Длина аудиоцикла, с","Файл повторяется с этим интервалом, пока объект существует. Длина определяется при загрузке; её можно уточнить вручную.",clip.Duration,.05,120,v=>{clip.Duration=v;update();},"Интервал повтора");}
  void DrawBuildStages(FlowLayoutPanel f,Entity e){Header(f,"Этапы строительства");f.Controls.Add(Theme.Label("Штатная сборка Forts добавляет слои изображения по процентам прогресса. Первый слой виден с 0%, следующие добавляются поверх него. Можно задать до 32 этапов; для полных картинок используйте одинаковый холст и учитывайте наложение прозрачных областей.",9));var line=new FlowLayoutPanel{AutoSize=true,Width=490};line.Controls.Add(Theme.Label("Количество этапов",9,true));var count=new NumericUpDown{Minimum=0,Maximum=32,Value=Math.Min(32,e.BuildStages.Count),Width=75,BackColor=Theme.Input,ForeColor=Theme.Text};count.ValueChanged+=(s,ev)=>{int n=(int)count.Value;while(e.BuildStages.Count<n)e.BuildStages.Add(new BuildStage());if(e.BuildStages.Count>n)e.BuildStages.RemoveRange(n,e.BuildStages.Count-n);for(int i=0;i<n;i++)e.BuildStages[i].Progress=n==1?0:(int)Math.Round(100.0*i/(n-1));Mark();ShowEntityTab(e,"Ресурсы");};line.Controls.Add(count);f.Controls.Add(line);f.Controls.Add(Theme.Label("При изменении количества пороги распределяются от 0 до 100%. Затем каждый порог можно изменить вручную.",8));
   for(int i=0;i<e.BuildStages.Count;i++){int index=i;var stage=e.BuildStages[i];var row=new Panel{Width=480,Height=126,BackColor=Theme.Input,Margin=new Padding(0,6,0,8)};var title=Theme.Label("ЭТАП "+(i+1),9,true);title.Location=new Point(12,6);row.Controls.Add(title);var pc=new NumericUpDown{Minimum=0,Maximum=100,Value=stage.Progress,Width=68,Location=new Point(110,9),BackColor=Theme.Card,ForeColor=Theme.Text};pc.ValueChanged+=(s,ev)=>{stage.Progress=(int)pc.Value;Mark();};row.Controls.Add(pc);var suffix=Theme.Label("% готовности",8);suffix.Location=new Point(188,9);row.Controls.Add(suffix);var img=Assets.Image(stage.Image.Length>0?stage.Image:e.Texture,project.GameRoot);if(img!=null)row.Controls.Add(new PictureBox{Image=img,SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(12,42),Size=new Size(70,70)});var upload=Theme.Button(stage.Image.Length>0?"Заменить изображение":"Изображение этапа",()=>Safe(()=>{using(var d=new OpenFileDialog{Filter="Изображения|*.png;*.jpg;*.jpeg;*.bmp"})if(UiDialogs.Show(d,this)==DialogResult.OK){stage.Image=Assets.Import(d.FileName,true);stage.Name=Path.GetFileName(d.FileName);Mark();ShowEntityTab(e,"Ресурсы");}}));upload.Location=new Point(96,45);row.Controls.Add(upload);var file=Theme.Label(stage.Name.Length>0?stage.Name:"Используется основной спрайт",8);file.Location=new Point(96,88);file.MaximumSize=new Size(360,0);row.Controls.Add(file);var remove=Theme.Button("×",()=>{e.BuildStages.RemoveAt(index);Mark();ShowEntityTab(e,"Ресурсы");});remove.AutoSize=false;remove.MinimumSize=new Size(28,28);remove.Size=new Size(28,28);remove.Padding=Padding.Empty;remove.Location=new Point(435,9);row.Controls.Add(remove);f.Controls.Add(row);}
   if(e.BuildStages.Count>0)f.Controls.Add(Theme.Label("Предпросмотр этапов — ползунок «Готовность» над строительной площадкой. Изображения приводятся к одному размеру холста.",9));
  }
